=== src/App.jsx ===
import React, { useState, useEffect, useMemo } from 'react';
import {
  Users, CheckCircle2, XCircle, Send, Plus, Trash2, Edit2, 
  Search, Copy, Check, MessageSquare, CreditCard, Bell, RefreshCw
} from 'lucide-react';

const INITIAL_MEMBERS = [
  { id: '1', name: '김민준', phone: '010-1234-5678', role: '회장', paid: true, paidDate: '2025-02-01' },
  { id: '2', name: '이서연', phone: '010-2345-6789', role: '총무', paid: true, paidDate: '2025-02-02' },
  { id: '3', name: '박도윤', phone: '010-3456-7890', role: '회원', paid: false, paidDate: '' },
  { id: '4', name: '정예은', phone: '010-4567-8901', role: '회원', paid: false, paidDate: '' },
  { id: '5', name: '최현우', phone: '010-5678-9012', role: '회원', paid: true, paidDate: '2025-02-10' },
  { id: '6', name: '강지민', phone: '010-6789-0123', role: '신입', paid: false, paidDate: '' },
];

const INITIAL_SETTINGS = {
  feeName: '2025년 1학기 정기 회비',
  amount: 30000,
  dueDate: '2025-03-15',
  bankName: '카카오뱅크',
  accountNumber: '3333-01-1234567',
  accountHolder: '이서연(총무)',
};

export default function App() {
  const [members, setMembers] = useState(() => {
    const saved = localStorage.getItem('club_members');
    return saved ? JSON.parse(saved) : INITIAL_MEMBERS;
  });

  const [settings, setSettings] = useState(() => {
    const saved = localStorage.getItem('club_fee_settings');
    return saved ? JSON.parse(saved) : INITIAL_SETTINGS;
  });

  const [search, setSearch] = useState('');
  const [filterPaid, setFilterPaid] = useState('all'); // all, paid, unpaid
  const [showMemberModal, setShowMemberModal] = useState(false);
  const [showReminderModal, setShowReminderModal] = useState(false);
  const [selectedTarget, setSelectedTarget] = useState(null); // null = 전체 미납자, member obj = 개별
  const [copied, setCopied] = useState(false);

  const [formMember, setFormMember] = useState({ id: '', name: '', phone: '', role: '회원', paid: false });

  useEffect(() => {
    localStorage.setItem('club_members', JSON.stringify(members));
  }, [members]);

  useEffect(() => {
    localStorage.setItem('club_fee_settings', JSON.stringify(settings));
  }, [settings]);

  // 통계 계산
  const stats = useMemo(() => {
    const total = members.length;
    const paidCount = members.filter((m) => m.paid).length;
    const unpaidCount = total - paidCount;
    const totalCollected = paidCount * settings.amount;
    const targetAmount = total * settings.amount;
    return { total, paidCount, unpaidCount, totalCollected, targetAmount };
  }, [members, settings.amount]);

  // 필터링된 멤버 리스트
  const filteredMembers = useMemo(() => {
    return members.filter((m) => {
      const matchSearch = m.name.toLowerCase().includes(search.toLowerCase()) || m.phone.includes(search);
      const matchStatus = filterPaid === 'all' ? true : filterPaid === 'paid' ? m.paid : !m.paid;
      return matchSearch && matchStatus;
    });
  }, [members, search, filterPaid]);

  const togglePaidStatus = (id) => {
    const today = new Date().toISOString().split('T')[0];
    setMembers((prev) =>
      prev.map((m) => {
        if (m.id === id) {
          const nextStatus = !m.paid;
          return { ...m, paid: nextStatus, paidDate: nextStatus ? today : '' };
        }
        return m;
      })
    );
  };

  const handleSaveMember = (e) => {
    e.preventDefault();
    if (!formMember.name.trim()) return;

    if (formMember.id) {
      setMembers((prev) => prev.map((m) => (m.id === formMember.id ? { ...formMember } : m)));
    } else {
      setMembers((prev) => [
        ...prev,
        {
          ...formMember,
          id: Date.now().toString(),
          paidDate: formMember.paid ? new Date().toISOString().split('T')[0] : '',
        },
      ]);
    }
    setShowMemberModal(false);
  };

  const deleteMember = (id) => {
    if (confirm('정말 삭제하시겠습니까?')) {
      setMembers((prev) => prev.filter((m) => m.id !== id));
    }
  };

  const openReminder = (member = null) => {
    setSelectedTarget(member);
    setShowReminderModal(true);
    setCopied(false);
  };

  // 알림 메시지 생성
  const generateMessage = () => {
    const unpaidNames = members.filter((m) => !m.paid).map((m) => m.name).join(', ');
    const targetName = selectedTarget ? `${selectedTarget.name}님` : `${unpaidNames} 학우님`;

    return `[동아리 회비 납부 안내]\n\n안녕하세요, ${targetName}!\n${settings.feeName} 납부 관련하여 안내드립니다.\n\n▪ 납부 금액: ${settings.amount.toLocaleString()}원\n▪ 납부 기한: ${settings.dueDate}까지\n▪ 입금 계좌: ${settings.bankName} ${settings.accountNumber} (${settings.accountHolder})\n\n원활한 동아리 행사 및 운영을 위해 기한 내 입금 부탁드립니다.\n(이미 입금하셨다면 총무에게 확인 메시지 부탁드립니다.)\n감사합니다!`;
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(generateMessage());
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const sendSms = (phone) => {
    const body = encodeURIComponent(generateMessage());
    window.open(`sms:${phone}?body=${body}`);
  };

  return (
    <div className="min-h-screen bg-slate-100 p-4 md:p-8">
      <div className="max-w-5xl mx-auto space-y-6">
        {/* Header */}
        <header className="bg-white rounded-2xl shadow-sm p-6 flex flex-col md:flex-row md:items-center justify-between gap-4 border border-slate-200">
          <div>
            <div className="flex items-center gap-2">
              <span className="p-2 bg-indigo-50 text-indigo-600 rounded-lg">
                <CreditCard className="w-6 h-6" />
              </span>
              <h1 className="text-2xl font-bold text-slate-800">동아리 회비 관리</h1>
            </div>
            <p className="text-slate-500 text-sm mt-1">회원별 납부 상태를 모니터링하고 알림 메시지를 빠르게 전송하세요.</p>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => openReminder(null)}
              className="flex items-center gap-2 bg-rose-500 hover:bg-rose-600 text-white px-4 py-2.5 rounded-xl font-medium shadow-sm transition"
            >
              <Bell className="w-4 h-4" />
              미납자 전체 알림
            </button>
            <button
              onClick={() => {
                setFormMember({ id: '', name: '', phone: '', role: '회원', paid: false });
                setShowMemberModal(true);
              }}
              className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2.5 rounded-xl font-medium shadow-sm transition"
            >
              <Plus className="w-4 h-4" />
              회원 등록
            </button>
          </div>
        </header>

        {/* Dashboard Cards */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
            <p className="text-slate-500 text-xs font-semibold uppercase">전체 회원</p>
            <div className="flex items-baseline justify-between mt-2">
              <span className="text-3xl font-extrabold text-slate-800">{stats.total}명</span>
              <Users className="w-5 h-5 text-slate-400" />
            </div>
          </div>
          <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
            <p className="text-emerald-600 text-xs font-semibold uppercase">납부 완료</p>
            <div className="flex items-baseline justify-between mt-2">
              <span className="text-3xl font-extrabold text-emerald-600">{stats.paidCount}명</span>
              <CheckCircle2 className="w-5 h-5 text-emerald-500" />
            </div>
          </div>
          <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
            <p className="text-rose-600 text-xs font-semibold uppercase">미납 인원</p>
            <div className="flex items-baseline justify-between mt-2">
              <span className="text-3xl font-extrabold text-rose-600">{stats.unpaidCount}명</span>
              <XCircle className="w-5 h-5 text-rose-500" />
            </div>
          </div>
          <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
            <p className="text-indigo-600 text-xs font-semibold uppercase">현재 징수액</p>
            <div className="flex items-baseline justify-between mt-2">
              <span className="text-2xl font-extrabold text-indigo-700">
                {stats.totalCollected.toLocaleString()}원
              </span>
              <span className="text-xs text-slate-400">/ {stats.targetAmount.toLocaleString()}원</span>
            </div>
          </div>
        </div>

        {/* Search & Filter */}
        <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-col sm:flex-row gap-3 items-center justify-between">
          <div className="relative w-full sm:w-80">
            <Search className="w-4 h-4 absolute left-3 top-3 text-slate-400" />
            <input
              type="text"
              placeholder="이름 또는 전화번호 검색"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-full pl-9 pr-4 py-2 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none text-sm"
            />
          </div>
          <div className="flex items-center gap-2 w-full sm:w-auto">
            <button
              onClick={() => setFilterPaid('all')}
              className={`px-3 py-1.5 rounded-lg text-sm font-medium transition ${
                filterPaid === 'all' ? 'bg-slate-800 text-white' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
              }`}
            >
              전체 ({members.length})
            </button>
            <button
              onClick={() => setFilterPaid('unpaid')}
              className={`px-3 py-1.5 rounded-lg text-sm font-medium transition ${
                filterPaid === 'unpaid' ? 'bg-rose-600 text-white' : 'bg-rose-50 text-rose-700 hover:bg-rose-100'
              }`}
            >
              미납만 ({stats.unpaidCount})
            </button>
            <button
              onClick={() => setFilterPaid('paid')}
              className={`px-3 py-1.5 rounded-lg text-sm font-medium transition ${
                filterPaid === 'paid' ? 'bg-emerald-600 text-white' : 'bg-emerald-50 text-emerald-700 hover:bg-emerald-100'
              }`}
            >
              납부완료 ({stats.paidCount})
            </button>
          </div>
        </div>

        {/* Member Table */}
        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
              <thead className="bg-slate-50 text-slate-500 uppercase border-b border-slate-200 text-xs">
                <tr>
                  <th className="px-6 py-4">상태</th>
                  <th className="px-6 py-4">이름 (역할)</th>
                  <th className="px-6 py-4">연락처</th>
                  <th className="px-6 py-4">납부일시</th>
                  <th className="px-6 py-4 text-center">알림 및 조치</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {filteredMembers.length === 0 ? (
                  <tr>
                    <td colSpan="5" className="text-center py-10 text-slate-400">
                      등록된 회원이 없거나 조건에 맞는 회원이 없습니다.
                    </td>
                  </tr>
                ) : (
                  filteredMembers.map((member) => (
                    <tr key={member.id} className="hover:bg-slate-50 transition">
                      <td className="px-6 py-4 whitespace-nowrap">
                        <button
                          onClick={() => togglePaidStatus(member.id)}
                          className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold transition ${
                            member.paid
                              ? 'bg-emerald-100 text-emerald-800 hover:bg-emerald-200'
                              : 'bg-rose-100 text-rose-800 hover:bg-rose-200'
                          }`}
                        >
                          {member.paid ? <CheckCircle2 className="w-3.5 h-3.5" /> : <XCircle className="w-3.5 h-3.5" />}
                          {member.paid ? '납부완료' : '미납'}
                        </button>
                      </td>
                      <td className="px-6 py-4 font-medium text-slate-900 whitespace-nowrap">
                        {member.name}
                        <span className="ml-2 text-xs text-slate-400 font-normal">({member.role})</span>
                      </td>
                      <td className="px-6 py-4 text-slate-600 whitespace-nowrap">{member.phone}</td>
                      <td className="px-6 py-4 text-slate-500 text-xs whitespace-nowrap">
                        {member.paid ? member.paidDate || '납부 확인됨' : '-'}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-center space-x-2">
                        {!member.paid && (
                          <button
                            onClick={() => openReminder(member)}
                            className="inline-flex items-center gap-1 text-xs px-2.5 py-1.5 bg-rose-50 text-rose-600 rounded-lg hover:bg-rose-100 font-medium"
                          >
                            <Send className="w-3.5 h-3.5" /> 알림문구
                          </button>
                        )}
                        <button
                          onClick={() => {
                            setFormMember(member);
                            setShowMemberModal(true);
                          }}
                          className="p-1.5 text-slate-400 hover:text-indigo-600 rounded-md"
                          title="수정"
                        >
                          <Edit2 className="w-4 h-4" />
                        </button>
                        <button
                          onClick={() => deleteMember(member.id)}
                          className="p-1.5 text-slate-400 hover:text-rose-600 rounded-md"
                          title="삭제"
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>

        {/* Setting Card */}
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-4">
          <h2 className="text-lg font-bold text-slate-800">회비 및 입금 계좌 설정</h2>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="text-xs font-semibold text-slate-500">회비 명칭</label>
              <input
                type="text"
                value={settings.feeName}
                onChange={(e) => setSettings({ ...settings, feeName: e.target.value })}
                className="mt-1 w-full p-2 border border-slate-200 rounded-lg text-sm"
              />
            </div>
            <div>
              <label className="text-xs font-semibold text-slate-500">금액 (원)</label>
              <input
                type="number"
                value={settings.amount}
                onChange={(e) => setSettings({ ...settings, amount: Number(e.target.value) })}
                className="mt-1 w-full p-2 border border-slate-200 rounded-lg text-sm"
              />
            </div>
            <div>
              <label className="text-xs font-semibold text-slate-500">납부 마감일</label>
              <input
                type="date"
                value={settings.dueDate}
                onChange={(e) => setSettings({ ...settings, dueDate: e.target.value })}
                className="mt-1 w-full p-2 border border-slate-200 rounded-lg text-sm"
              />
            </div>
            <div>
              <label className="text-xs font-semibold text-slate-500">은행명</label>
              <input
                type="text"
                value={settings.bankName}
                onChange={(e) => setSettings({ ...settings, bankName: e.target.value })}
                className="mt-1 w-full p-2 border border-slate-200 rounded-lg text-sm"
              />
            </div>
            <div>
              <label className="text-xs font-semibold text-slate-500">계좌번호</label>
              <input
                type="text"
                value={settings.accountNumber}
                onChange={(e) => setSettings({ ...settings, accountNumber: e.target.value })}
                className="mt-1 w-full p-2 border border-slate-200 rounded-lg text-sm"
              />
            </div>
            <div>
              <label className="text-xs font-semibold text-slate-500">예금주</label>
              <input
                type="text"
                value={settings.accountHolder}
                onChange={(e) => setSettings({ ...settings, accountHolder: e.target.value })}
                className="mt-1 w-full p-2 border border-slate-200 rounded-lg text-sm"
              />
            </div>
          </div>
        </div>
      </div>

      {/* Member Add/Edit Modal */}
      {showMemberModal && (
        <div className="fixed inset-0 bg-black/40 flex items-center justify-center p-4 z-50">
          <div className="bg-white w-full max-w-md rounded-2xl p-6 shadow-xl space-y-4">
            <h3 className="text-lg font-bold text-slate-800">
              {formMember.id ? '회원 정보 수정' : '새 회원 등록'}
            </h3>
            <form onSubmit={handleSaveMember} className="space-y-3">
              <div>
                <label className="text-xs font-semibold text-slate-600">이름</label>
                <input
                  type="text"
                  required
                  value={formMember.name}
                  onChange={(e) => setFormMember({ ...formMember, name: e.target.value })}
                  className="mt-1 w-full p-2 border border-slate-200 rounded-lg text-sm"
                  placeholder="홍길동"
                />
              </div>
              <div>
                <label className="text-xs font-semibold text-slate-600">전화번호</label>
                <input
                  type="text"
                  value={formMember.phone}
                  onChange={(e) => setFormMember({ ...formMember, phone: e.target.value })}
                  className="mt-1 w-full p-2 border border-slate-200 rounded-lg text-sm"
                  placeholder="010-0000-0000"
                />
              </div>
              <div>
                <label className="text-xs font-semibold text-slate-600">역할/구분</label>
                <input
                  type="text"
                  value={formMember.role}
                  onChange={(e) => setFormMember({ ...formMember, role: e.target.value })}
                  className="mt-1 w-full p-2 border border-slate-200 rounded-lg text-sm"
                  placeholder="회원, 임원 등"
                />
              </div>
              <div className="flex items-center gap-2 pt-2">
                <input
                  type="checkbox"
                  id="paidCheck"
                  checked={formMember.paid}
                  onChange={(e) => setFormMember({ ...formMember, paid: e.target.checked })}
                  className="w-4 h-4 text-indigo-600 rounded"
                />
                <label htmlFor="paidCheck" className="text-sm font-medium text-slate-700">
                  이미 납부 완료함
                </label>
              </div>
              <div className="flex justify-end gap-2 pt-4">
                <button
                  type="button"
                  onClick={() => setShowMemberModal(false)}
                  className="px-4 py-2 border rounded-xl text-sm font-medium text-slate-600 hover:bg-slate-50"
                >
                  취소
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl text-sm font-medium"
                >
                  저장
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Reminder / Notification Modal */}
      {showReminderModal && (
        <div className="fixed inset-0 bg-black/40 flex items-center justify-center p-4 z-50">
          <div className="bg-white w-full max-w-lg rounded-2xl p-6 shadow-xl space-y-4">
            <div className="flex items-center justify-between">
