=== src/core/feeLogic.js ===
export function calculateStats(members, amount) {
  const total = members.length;
  const paidCount = members.filter((m) => m.paid).length;
  const unpaidCount = total - paidCount;
  return {
    total,
    paidCount,
    unpaidCount,
    totalCollected: paidCount * amount,
    targetAmount: total * amount,
  };
}

export function filterMembers(members, search, filterPaid) {
  const query = search.trim().toLowerCase();
  return members.filter((m) => {
    const matchSearch = !query || m.name.toLowerCase().includes(query) || m.phone.includes(query);
    const matchStatus = filterPaid === 'all' ? true : filterPaid === 'paid' ? m.paid : !m.paid;
    return matchSearch && matchStatus;
  });
}

export function toggleMemberPaid(members, id) {
  const today = new Date().toISOString().split('T')[0];
  return members.map((m) => {
    if (m.id === id) {
      const nextPaid = !m.paid;
      return { ...m, paid: nextPaid, paidDate: nextPaid ? today : '' };
    }
    return m;
  });
}

export function upsertMember(members, memberData) {
  if (memberData.id) {
    return members.map((m) => (m.id === memberData.id ? { ...memberData } : m));
  }
  const today = new Date().toISOString().split('T')[0];
  return [
    ...members,
    {
      ...memberData,
      id: Date.now().toString(),
      paidDate: memberData.paid ? today : '',
    },
  ];
}

export function generateReminderMessage(settings, members, targetMember = null) {
  const unpaidNames = members.filter((m) => !m.paid).map((m) => m.name).join(', ');
  const targetName = targetMember ? `${targetMember.name}님` : `${unpaidNames} 학우님`;

  return `[동아리 회비 납부 안내]\n\n안녕하세요, ${targetName}!\n${settings.feeName} 납부 관련하여 안내드립니다.\n\n▪ 납부 금액: ${settings.amount.toLocaleString()}원\n▪ 납부 기한: ${settings.dueDate}까지\n▪ 입금 계좌: ${settings.bankName} ${settings.accountNumber} (${settings.accountHolder})\n\n원활한 동아리 행사 및 운영을 위해 기한 내 입금 부탁드립니다.\n(이미 입금하셨다면 총무에게 확인 메시지 부탁드립니다.)\n감사합니다!`;
}

